package com.gestourant.order;
import jakarta.validation.Valid; import jakarta.validation.constraints.Min; import jakarta.validation.constraints.NotNull; import jakarta.validation.constraints.Size; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class OrderController { private final OrderService service; public OrderController(OrderService s){service=s;} @PostMapping("/tables/{tableId}/orders") @ResponseStatus(HttpStatus.CREATED) public RestaurantOrder open(@PathVariable Long tableId){return service.open(tableId);}@GetMapping("/tables/{tableId}/orders/open") public RestaurantOrder getOpenByTable(@PathVariable Long tableId){return service.getOpenByTable(tableId);}@GetMapping("/orders/{id}") public RestaurantOrder get(@PathVariable Long id){return service.get(id);}@PostMapping("/orders/{id}/items") public RestaurantOrder addItem(@PathVariable Long id,@Valid @RequestBody ItemRequest r){return service.addItem(id,r.productId(),r.quantity());}@PatchMapping("/orders/{orderId}/items/{itemId}") public RestaurantOrder updateItemIngredients(@PathVariable Long orderId,@PathVariable Long itemId,@Valid @RequestBody ItemModificationRequest r){return service.updateItemIngredients(orderId,itemId,r.removedIngredients());}@DeleteMapping("/orders/{orderId}/items/{itemId}") public RestaurantOrder removeItem(@PathVariable Long orderId,@PathVariable Long itemId){return service.removeItem(orderId,itemId);}@PostMapping("/orders/{id}/close") @ResponseStatus(HttpStatus.CREATED) public Invoice close(@PathVariable Long id,@Valid @RequestBody CloseRequest r){return service.close(id,r.paymentMethod());} public record ItemRequest(@NotNull Long productId,@NotNull @Min(1) Integer quantity){} public record ItemModificationRequest(@Size(max=500) String removedIngredients){} public record CloseRequest(@NotNull PaymentMethod paymentMethod){} }
